#!/bin/bash
set -e

echo "Preparando LUXOR Watches para o Render..."

ARCHIVE="/tmp/luxor-store-render.zip"

python3 - <<'PY'
import base64
from pathlib import Path

data = """"""
Path("/tmp/luxor-store-render.zip").write_bytes(base64.b64decode(data))
print("Pacote LUXOR extraído para /tmp.")
PY

unzip -o "$ARCHIVE" -d . >/dev/null
rm -f "$ARCHIVE"

echo "Instalando dependências..."
npm install

echo "LUXOR Watches pronto."
